// ==========================================
// FILE: make-golden-saves.mjs
// ==========================================
// Builds the golden save files in tests/golden-saves/ from the real game at the pre-rebuild
// baseline. Run once (node scripts/browser/make-golden-saves.mjs); after that the files are
// fixed reference data and must never be regenerated by later rebuild steps.
//   <name>.json          the save as the game wrote it (some hand-aged into older formats)
//   <name>.expected.json what the save checker turns it into (checked by tests/golden-saves.test.js)
//   <name>.resaved.json  what the game saves right after loading it (checked by the browser checks)
import { mkdir, writeFile } from "node:fs/promises";
import { startGame } from "./harness.mjs";

const OUT = new URL("../../tests/golden-saves/", import.meta.url);

async function playShortShift(h, seconds) {
  await h.game((scene) => scene.startNextShift());
  await h.page.waitForFunction(() => window.__game.scene.getScene("scene-game").shiftClock.started);
  await h.wait(seconds * 1000);
  await h.game((scene) => { scene.shiftClock.elapsedMs = 12 * 35 * 1000 - 200; });
  await h.page.waitForFunction(() => window.__game.scene.getScene("scene-game").shiftEnded, null, { timeout: 240000 });
}

const serialize = (h) => h.game((scene) => JSON.parse(JSON.stringify(scene.serialize())));

const h = await startGame();
const saves = {};
let floorSpot = null;
try {
  await h.newGame();
  saves["new-game"] = await serialize(h);

  // Mid-game: two stocked shelves, one employee (level 5 allows only one), one played shift, crates on the pad.
  await h.game((scene) => {
    scene.playerState.shopLevel = 5;
    scene.playerState.credits += 20000;
    scene.debugQuickstart({ shelfCount: 2, itemCount: 8 });
    scene.playerState.hireEmployee("tavi_stock_clerk");
    scene.playerState.hireEmployee("sera_floor_assistant");
  });
  await playShortShift(h, 45);
  await h.game((scene) => {
    scene.endDay();
    const itemId = scene.fixtures.shelves()[0].placements[0].itemId;
    scene.placeSupplyOrder(new Map([[itemId, 3]]));
  });
  saves["mid-game"] = await serialize(h);
  floorSpot = await h.game((scene) => ({ x: scene.storeDoor.x, y: scene.storeDoor.y + 64 * 4, tile: 64 }));

  // Every expansion open.
  await h.game((scene) => {
    for (const zone of scene.room.zones) if (zone.locked) scene.room.unlockZone(zone.id);
    scene.refreshCamera();
  });
  saves["expanded-shop"] = await serialize(h);

  // Trash on the floor.
  await h.game((scene) => {
    const door = scene.storeDoor;
    for (let index = 0; index < 6; index += 1) scene.dropTrash(door.x - 96 + index * 32, door.y + 96);
  });
  saves["trash"] = await serialize(h);
} finally {
  await h.close();
}

const clone = (value) => JSON.parse(JSON.stringify(value));
const mid = saves["mid-game"];

// Crates stacked on the floor, three carried, and one in mid-throw.
{
  const save = clone(mid);
  const padCrate = save.crates.find((crate) => crate.itemId);
  const itemId = padCrate.itemId;
  const at = (x, y, extra = {}) => ({ kind: "item", itemId, quantity: 2, x, y, velocityX: 0, velocityY: 0, ...extra });
  const baseX = floorSpot.x - floorSpot.tile * 2;
  const baseY = floorSpot.y;
  save.crates.push(
    at(baseX, baseY, { stack: [{ kind: "item", itemId, quantity: 1 }, { kind: "item", itemId, quantity: 3 }] }),
    at(baseX + floorSpot.tile * 4, baseY, { velocityX: 180, velocityY: 0,
      launch: { remainingMs: 40, accelerationX: 900, accelerationY: 0, maxSpeed: 420 },
      flight: { height: 12, fallSpeed: 30 } }),
  );
  save.carriedCrates = [
    { kind: "item", itemId, quantity: 1 },
    { kind: "item", itemId: null, quantity: 0 },
    { kind: "item", itemId, quantity: 4 },
  ];
  save.carriedCrate = save.carriedCrates.at(-1);
  saves["crates-in-motion"] = save;
}

// From before contracts were split: no contractsSplit flag, so split-off contracts are added.
{
  const save = clone(mid);
  delete save.playerState.contractsSplit;
  save.playerState.activeLicenses = [...new Set([...save.playerState.activeLicenses, "lic_start_rations"])];
  saves["before-contract-split"] = save;
}

// Previous layout version: retired shelf, retired contract, old hovercart, removed employee job.
{
  const save = clone(mid);
  save.layoutVersion = 9;
  const itemId = save.crates.find((crate) => crate.itemId).itemId;
  save.fixtures.push({ id: "retired_bulk_01", type: "shelf_bulk", gx: 1, gy: 1, rotation: 0,
    placements: [{ itemId, gx: 0, gy: 0, w: 1, h: 1, rotated: false, quantity: 5 }] });
  save.crates.push({ kind: "fixture", typeId: "locker_single", itemId: null, quantity: 0,
    x: save.crates[0].x, y: save.crates[0].y, velocityX: 0, velocityY: 0 });
  save.playerState.activeLicenses.push("lic_fixture_expanded");
  save.playerState.hovercart = { capacity: 25, stock: [{ itemId, quantity: 4 }] };
  const [employeeId] = save.playerState.hiredEmployees;
  save.playerState.employeeJobPriorities[employeeId] = ["load_storage", "register", "stock_shelves"];
  save.playerState.employeeSkills[employeeId] = { register: 1, stock_shelves: 1, load_storage: 3 };
  saves["older-layout"] = save;
}

await mkdir(OUT, { recursive: true });
const { readFile } = await import("node:fs/promises");
const { DatabaseManager } = await import("../../js/logic/DatabaseManager.js");
const { validateShopSave } = await import("../../js/logic/ShopSave.js");
const database = new DatabaseManager();
database.loadItemsJSON(JSON.parse(await readFile(new URL("../../data/Items.json", import.meta.url), "utf8")));
database.loadLicensesJSON(JSON.parse(await readFile(new URL("../../data/Licenses.json", import.meta.url), "utf8")));
const write = (name, value) => writeFile(new URL(name, OUT), `${JSON.stringify(value, null, 1)}\n`);

const checker = await startGame();
try {
  for (const [name, save] of Object.entries(saves)) {
    await write(`${name}.json`, save);
    await write(`${name}.expected.json`, validateShopSave(clone(save), database));
    await checker.loadSave(clone(save));
    await write(`${name}.resaved.json`, await checker.game((scene) => JSON.parse(scene.lastSavedSnapshot)));
  }
  if (checker.errors().length) throw new Error(JSON.stringify(checker.errors()));
} finally {
  await checker.close();
}
console.log(`Wrote ${Object.keys(saves).length} golden saves.`);
